from pathlib import Path
import json,html,datetime
D=Path(__file__).parent;Q=D/'audit'
suites=[]
for name,label in [('engine-qa.json','53 scenario engine checks'),('oracle-qa.json','Independent original-workbook finance replay'),('browser-qa.json','53 scenarios across six tabs and actual Excel exports'),('rebuild-browser-qa.json','Five requested ExCo corrections'),('final-export-browser-qa.json','Final build scenario downloads'),('export-qa.json','Downloaded scenario workbooks and ROI metadata'),('scenario-download-qa.json','Current / saved revision / inclusion / filtered downloads'),('compatibility-qa.json','Prior scenarios, ROI boundaries and undo'),('final-ui-qa.json','Final carryover demand display and export wording')]:
 data=json.loads((Q/name).read_text(encoding='utf8'));checks=data['checks'];passed=sum(c.get('passed',c.get('status')=='PASS') for c in checks)
 suites.append(dict(file=name,label=label,checks=len(checks),passed=passed,fatal=data.get('fatal')))
 assert passed==len(checks) and not data.get('fatal'),name
total=sum(x['checks'] for x in suites)
cases=json.loads((Q/'scenarios.json').read_text(encoding='utf8'))['scenarios']
E=html.escape
style='body{font:16px Calibri,Arial;line-height:1.5;color:#00126e;background:#f5f8fc;margin:0}main{max-width:1200px;margin:35px auto;padding:30px;background:white}h1{font-size:32px}h2{margin-top:32px}table{border-collapse:collapse;width:100%}td,th{text-align:left;padding:10px;border-bottom:1px solid #d5dae0}th{background:#eaf4ff}.banner{padding:20px;background:#e5f4e8;border-left:5px solid #008800}.note{padding:16px;background:#fff5da}a{color:#0b5ed7}code{word-break:break-all}'
def doc(title,body):return '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+E(title)+'</title><style>'+style+'</style><main><h1>'+E(title)+'</h1>'+body+'</main></html>'
changes=[('Carryover ROI in Tab 2','Restored 0–10x slider and numeric input in 0.5x steps. Confirmed baselines are exempt; 10x is baseline-only, 0x applies no ROI filter to other eligible carryovers. Default 10x preserves current Optimal funding.'),('Scenario Excel downloads','Visible current/saved revision selector, complete/inclusions/filtered scope and download next to saved revisions in Tab 2. Filenames identify scenario, revision and scope. Selected Programs and Scenario Selection sheets make scope explicit; full finance evidence is retained.'),('Overall State navigation','Overall State replaces Company position and the all-leaders dropdown label. Compare options and its recommendation navigation are removed from ExCo.'),('Visible funding decisions and sorting','My portfolio, Decisions and Funding opportunities provide Opt in, Opt out, Partial funding, Automatic and request/score review. All changes preview before apply. Sort by Hard Benefits, requested budget or score in either direction; unknown hard benefits remain last.'),('One shared bubble chart','ExCo calls the same renderer as Tabs 3, 4 and 6: logarithmic amount scale, merit axis, funding/Decision Band colors, legend totals, demand/Hard Benefits toggle and source detail interactions. Axis and color synchronize both ways.')]
body='<p>Recreated build · 30 September 2026 · v5.10.0</p><div class="banner"><b>'+str(total)+' / '+str(total)+' validation assertions passed.</b> 53 scenarios: 32 existing configurations and all 21 ROI positions. These checks cover the implemented behavior; they do not constitute business approval or a claim of global portfolio optimality.</div><p><a href="AOP2027-IT-Portfolio-Scenario-Modelling-v5.10.0.html">Open rebuilt modeler</a> · <a href="ExCo-PRD-and-Requirements-v5.10.0.html">PRD and requirements</a></p><h2>Five corrections</h2><table><tr><th>Request</th><th>Implemented behavior</th></tr>'+''.join('<tr><td>'+E(a)+'</td><td>'+E(b)+'</td></tr>' for a,b in changes)+'</table>'
body+='<h2>Validation evidence</h2><table><tr><th>Suite</th><th>Passed</th><th>Evidence</th></tr>'+''.join('<tr><td>'+E(s['label'])+'</td><td>'+str(s['passed'])+' / '+str(s['checks'])+'</td><td><a href="audit/'+s['file']+'">Detailed assertions</a></td></tr>' for s in suites)+'</table>'
body+='<h2>Scenario results at exact precision</h2><p>Lower ROI settings deliberately allow more unconfirmed carryovers through source eligibility. Under the fixed budget, their funding can displace Sustain and Value. Confirmed baseline eligibility remains ROI-exempt. Whole-Programs fit can affect utilization.</p><table><tr><th>Scenario</th><th>ROI x</th><th>Base funded M€</th><th>Carryover M€</th><th>Sustain M€</th><th>Value M€</th><th>Total IT M€</th></tr>'+''.join('<tr><td>'+E(c['name'])+'</td><td>'+str(c['settings']['carry'])+'</td><td>'+f"{c['result']['totals']['allocation']:.6f}"+'</td>'+''.join('<td>'+f"{c['result']['stages'][i]['allocation']:.6f}"+'</td>' for i in [1,2,3])+'<td>'+f"{c['result']['finance']['totals']['total']:.6f}"+'</td></tr>' for c in cases)+'</table>'
body+='<h2>Key findings and remaining data limitations</h2><ul><li>Default Optimal remains 99.963 M€ base funding, 5.190 M€ PMI and 470.314463 M€ Operations, totaling 575.467463 M€.</li><li>Approved EW unallocated share remains 22.6303317536%. The 40 M€ charging key remains excluded from demand.</li><li>Confirmed carryovers use min(request, approved baseline). Other eligible carryovers use the restored ROI filter. Source conditions, manual overrides, tolerance and whole-Programs fit still apply.</li><li>ROI means submitted lifetime benefit divided by scenario request; it is not an annual cash return. Hard and Soft claims remain separate.</li><li>Existing v5.9 portable scenarios retain baseline-only eligibility until the ROI control is changed, preventing an old unused 0x setting from silently changing allocation.</li><li>Saved scenarios are browser-local. Use portable JSON to open scenarios saved in another browser or previous build; then download that scenario from this build.</li><li>Operations remains fixed. Funding changes recalculate the same source-linked receiving-organisation ledger in ExCo, all six tabs and Excel.</li><li>No known blocking defect remains in the tested workflows. Original workbooks and v5.7.0–v5.9.0 are preserved.</li></ul><p>Independent replay used the original Programs and Operations workbooks, not exported application totals as its allocation authority. See source-row and recipient assertions above.</p>'
(D/'ExCo-QA-report-v5.10.0.html').write_text(doc('AOP 2027 · ExCo rebuild validation',body),encoding='utf8')
req='<p>This addendum supersedes conflicting ExCo interface and carryover-threshold text in v5.9.0. Source finance allocation rules remain unchanged. User request: recreate the build for the five missed workflows.</p><table><tr><th>ID</th><th>Requirement / acceptance</th></tr>'+''.join('<tr><td>EXCO510-'+str(i+1).zfill(2)+'</td><td><b>'+E(a)+'</b><br>'+E(b)+'</td></tr>' for i,(a,b) in enumerate(changes))+'</table><h2>Finance rule contract</h2><p>Default 100 M€ budget, ROI 10x baseline-only, confirmed baseline caps, unchanged priority ordering, source decision eligibility and merit calculation. At 0–9.5x, unconfirmed carryovers pass when their quantified benefit/request ratio meets the threshold; 0x removes this ratio test. Missing ratio fails positive thresholds. Confirmed baseline eligibility is unaffected by the threshold. Engine and preview settings are persisted and included in Excel.</p><h2>Decision contract</h2><p>Opt in funds the current request; Opt out funds zero; Partial funding requires an amount above zero and below the request; Automatic removes the manual override. These are manual scenario decisions, with rationale, preview, one event, undo and finalised-state protection. They preserve source data and share the same result with the workbench.</p><h2>Export contract</h2><p>Export the selected saved snapshot without activating or mutating it. Solve that snapshot with its own data, settings, overrides and reviews. Include scenario ID, name, revision, scope, exact selected rows and full financial/source evidence. Filtered scope uses current selected leaders and filters against the selected snapshot.</p><h2>Compatibility and evidence</h2><p>Prior v5.9 carry settings had no effect. Missing carryPolicy is therefore interpreted as baseline-only until the user operates the new control. This prevents silent funding drift on portable imports. New sessions use carryPolicy roi-v1 and 10x. Test evidence: '+str(total)+' assertions, 53 configurations and source-workbook replay.</p><p><a href="ExCo-QA-report-v5.10.0.html">Validation report</a></p>'
(D/'ExCo-PRD-and-Requirements-v5.10.0.html').write_text(doc('AOP 2027 · v5.10.0 PRD and requirements',req),encoding='utf8')
(Q/'validation-summary.json').write_text(json.dumps({'version':'5.10.0','assertions':total,'passed':total,'scenarios':53,'suites':suites},indent=2))
log=[{'phase':'Review','result':'Checked v5.6 ROI behavior, v5.9 controls, exports and shared chart renderer.'},{'phase':'Rebuild','result':'Implemented the five requested corrections in v5.10.0; previous builds preserved.'},{'phase':'Validate','result':str(total)+' assertions passed across 53 scenarios, UI workflows and downloaded Excel workbooks.'},{'phase':'Source replay','result':'Original-workbook Program selection and receiving organisation totals independently reconciled.'}]
(D/'Execution-log-v5.10.0.jsonl').write_text('\n'.join(json.dumps(x) for x in log)+'\n')
(D/'Execution-log-v5.10.0.html').write_text(doc('AOP 2027 · v5.10.0 execution log',''.join('<p><b>'+x['phase']+'</b> — '+x['result']+'</p>' for x in log)),encoding='utf8')
print(json.dumps({'assertions':total,'passed':total,'scenarios':53}))
